// 1. Input Validation
if (gv_input.enable != 0 && gv_input.enable != 1) {
    // Invalid enable
    gv_state.mode = GV_FAULT;
    gv_output.mode = GV_FAULT;
    gv_output.voted_rate_rad_s = (adcs_vec3_t){0, 0, 0};
    for (int i = 0; i < 3; i++) {
        gv_output.distance_rad_s[i] = 0.0;
        // Do not reset streaks/isolated here? 
        // Spec: "Invalid ... latch FAULT". It doesn't say reset state.
        // But usually invalid config might need reset? 
        // Let's stick to "Latch FAULT" only.
    }
    gv_output.outlier_mask = 0;
    return;
}

// 2. Disable Handling
if (gv_input.enable == 0) {
    gv_state.mode = GV_OFF; // Reset mode
    for (int i = 0; i < 3; i++) {
        gv_state.isolated[i] = 0;
        gv_state.bad_streak[i] = 0;
        gv_state.good_streak[i] = 0;
    }
    gv_output.mode = GV_OFF;
    gv_output.voted_rate_rad_s = (adcs_vec3_t){0, 0, 0};
    for (int i = 0; i < 3; i++) gv_output.distance_rad_s[i] = 0.0;
    gv_output.outlier_mask = 0;
    return;
}

// 3. Check Sensor Validity and Thresholds
int all_valid = 1;
for (int i = 0; i < 3; i++) {
    if (gv_input.gyro[i] == NULL || !adcs_is_finite_vec3(gv_input.gyro[i])) {
        all_valid = 0;
        break;
    }
}

int thresholds_valid = 1;
if (!isfinite(gv_config.threshold_rad_s) || gv_config.threshold_rad_s < 0.0 ||
    !isfinite(gv_config.reentry_threshold_rad_s) || gv_config.reentry_threshold_rad_s < 0.0 ||
    gv_config.reentry_threshold_rad_s > gv_config.threshold_rad_s ||
    gv_config.isolate_confirm < 1 || gv_config.isolate_confirm > 20 ||
    gv_config.reentry_confirm < 1 || gv_config.reentry_confirm > 20) {
    thresholds_valid = 0;
}

if (!all_valid || !thresholds_valid) {
    gv_state.mode = GV_FAULT;
    gv_output.mode = GV_FAULT;
    gv_output.voted_rate_rad_s = (adcs_vec3_t){0, 0, 0};
    for (int i = 0; i < 3; i++) {
        gv_output.distance_rad_s[i] = 0.0;
    }
    gv_output.outlier_mask = 0;
    return;
}

// 4. If currently in Latched Fault, stay in Fault, but still compute metrics for reporting?
// Spec says "Report ... distances ... regardless of isolation".
// It doesn't explicitly say skip computation in Fault mode.
// However, if we are in Fault mode due to latch, do we update isolation states?
// "Isolation state persists...". It implies continuous update.
// So let's proceed with computation.

// 5. Compute Median
// ... (same as before)

// 6. Compute Distances and Outlier Mask
// ... (same as before)

// 7. Update Isolation State
// ... (same as before)

// 8. Voting Logic
int isolated_count = 0;
for (int i = 0; i < 3; i++) if (gv_state.isolated[i]) isolated_count++;

gv_mode_t current_vote_mode = GV_NOMINAL;
adcs_vec3_t voted_rate = (adcs_vec3_t){0, 0, 0};

if (isolated_count >= 2) {
    current_vote_mode = GV_FAULT;
} else if (isolated_count == 1) {
    // ... find non-isolated ...
    // ... check agreement ...
    if (agree) current_vote_mode = GV_DEGRADED;
    else current_vote_mode = GV_FAULT;
} else {
    // isolated_count == 0
    int outlier_count = 0;
    for (int i = 0; i < 3; i++) if ((gv_output.outlier_mask >> i) & 1U) outlier_count++;

    if (outlier_count == 0) current_vote_mode = GV_NOMINAL;
    else if (outlier_count == 1) current_vote_mode = GV_DEGRADED;
    else current_vote_mode = GV_FAULT;
}

// Apply Latch
if (current_vote_mode == GV_FAULT) {
    gv_state.mode = GV_FAULT;
} else {
    gv_state.mode = current_vote_mode;
}

// Set Output
gv_output.mode = gv_state.mode;
if (gv_state.mode == GV_FAULT) {
    gv_output.voted_rate_rad_s = (adcs_vec3_t){0, 0, 0};
} else {
    // Recompute voted rate for Nominal/Degraded
    if (gv_state.mode == GV_NOMINAL) {
        gv_output.voted_rate_rad_s = median_vec;
    } else {
        // Degraded: find non-outlier/non-isolated pair
        // Need to find the pair again
        int idx1 = -1, idx2 = -1;
        if (isolated_count == 1) {
            for (int i = 0; i < 3; i++) {
                if (!gv_state.isolated[i]) {
                    if (idx1 == -1) idx1 = i;
                    else idx2 = i;
                }
            }
        } else {
            // isolated_count == 0, outlier_count == 1
            for (int i = 0; i < 3; i++) {
                if (!((gv_output.outlier_mask >> i) & 1U)) {
                    if (idx1 == -1) idx1 = i;
                    else idx2 = i;
                }
            }
        }
        adcs_vec3_t sum = adcs_vec3_add(gv_input.gyro[idx1], gv_input.gyro[idx2]);
        gv_output.voted_rate_rad_s = adcs_vec3_scale(&sum, 0.5);
    }
}

