if (sorted[1].x > sorted[2].x) { adcs_vec3_t t = sorted[1]; sorted[1] = sorted[2]; sorted[2] = t; }
if (sorted[0].x > sorted[1].x) { adcs_vec3_t t = sorted[0]; sorted[0] = sorted[1]; sorted[1] = t; }
median_vec.x = sorted[1].x;

