sorted[0] = *gv_input.gyro[0];
sorted[1] = *gv_input.gyro[1];
sorted[2] = *gv_input.gyro[2];
if (sorted[0].y > sorted[1].y) { adcs_vec3_t t = sorted[0]; sorted[0] = sorted[1]; sorted[1] = t; }
if (sorted[1].y > sorted[2].y) { adcs_vec3_t t = sorted[1]; sorted[1] = sorted[2]; sorted[2] = t; }
if (sorted[0].y > sorted[1].y) { adcs_vec3_t t = sorted[0]; sorted[0] = sorted[1]; sorted[1] = t; }
median_vec.y = sorted[1].y;

