sorted[1] = *gv_input.gyro[1];
sorted[2] = *gv_input.gyro[2];
if (sorted[0].z > sorted[1].z) { adcs_vec3_t t = sorted[0]; sorted[0] = sorted[1]; sorted[1] = t; }
